WORK=Path('/kaggle/working/application_transfer_run');CODE=WORK/'astro_application_transfer';WORK.mkdir(parents=True,exist_ok=True)
raw=base64.b64decode(''.join(ARCHIVE_B64.split()));got=hashlib.sha256(raw).hexdigest();assert got==EXPECTED_ARCHIVE,(got,EXPECTED_ARCHIVE)
marker=WORK/'SETUP_OK.json'
if not marker.exists() or json.loads(marker.read_text()).get('archive_sha256')!=EXPECTED_ARCHIVE:
    shutil.rmtree(CODE,ignore_errors=True);CODE.mkdir();archive=WORK/'embedded_code.tar.gz';archive.write_bytes(raw);tarfile.open(archive,'r:gz').extractall(CODE)
    subprocess.run([sys.executable,'-m','pip','install','-q','numpy==2.5.3','scikit-learn==1.9.1','xgboost==3.4.1','rebound==5.2.0','PyYAML==6.0.3','pytest==9.1.1'],check=True)
    subprocess.run([sys.executable,'-m','pip','install','-q','-e',str(CODE)],check=True)
    subprocess.run([sys.executable,'-m','pytest','-q',str(CODE/'tests')],cwd=CODE,check=True)
    marker.write_text(json.dumps({'archive_sha256':EXPECTED_ARCHIVE,'python':sys.version},indent=2)+'\n')
else:
    print('Reusing verified setup',marker.read_text(),flush=True)

ROOT=Path('/kaggle/working/application_pilot')
for config,name in [('field_calibrated.json','field_like_stellar'),('young_cluster_calibrated.json','young_cluster_like_stellar')]:
    out=ROOT/name;cmd=[sys.executable,'-m','astro_transfer.cli','pilot','--config',str(CODE/'configs'/config),'--out',str(out),'--n','10000','--workers','96','--start-id','0','--endpoint-override','300','--block-size','500']
    print('RUN',' '.join(cmd),flush=True);subprocess.run(cmd,cwd=CODE,check=True);summary=json.loads((out/'summary.json').read_text());assert summary['n']==10000 and sum(summary['status_counts'].values())==10000;print(json.dumps(summary,indent=2),flush=True)
bundle=shutil.make_archive('/kaggle/working/ALL_APPLICATIONS_10000','zip',root_dir=ROOT)
print('DONE',bundle,flush=True)
